//! Cargo-driven `acgenral.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is acgenral-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMain@12", Some(0x78120000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMain", Some(0x7ff77000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMain", Some(0x7ff77000000u64)),
        o => panic!("acgenral-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:c:shimlib", "import:uxtheme", "import:kernel32", "import:ntdll"],
        "x86_64" => &["body", "engine:c:shimlib", "import:uxtheme", "import:kernel32", "import:ntdll"],
        "aarch64" => &["body", "engine:c:shimlib", "import:uxtheme", "import:kernel32", "import:ntdll"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("acgenral-rust")
        .c_from_compile_db(
            "acgenral_shims",
            match arch.as_str() {
                "x86" => &["dll/appcompat/shims/genral/rust_cohab_stub.c"],
                "x86_64" => &["dll/appcompat/shims/genral/rust_cohab_stub.c", "dll/appcompat/shims/genral/msys2.c"],
                "aarch64" => &["dll/appcompat/shims/genral/rust_cohab_stub.c"],
                _ => unreachable!(),
            },
        )
        .spec2def("dll/appcompat/shims/genral/genral.spec", "acgenral.dll")
        .import_lib("dll/win32/uxtheme/uxtheme.spec", "uxtheme.dll", "uxtheme")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
